def transform(grid):
    g = np.array(grid)
    bg = background(g)
    objs = objects(g, bg=bg)
    key = lambda o: tuple(map(tuple, (o["grid"] != bg).astype(int)))
    lookup = {}
    for o in objs:
        if o["colour"] != 1:
            lookup.setdefault(key(o), o["colour"])
    out = g.copy()
    emit(out, "Start from the input; colour-1 shapes need a colour.")
    for o in objs:
        if o["colour"] != 1:
            continue
        c = lookup.get(key(o))
        if c is None:
            continue
        for (y, x) in o["cells"]:
            out[y, x] = c
        emit(out, f"Recolour the 1-shape at {o['box']} with colour {c}, the colour of the identical shape.")
    emit(out, "All colour-1 shapes now copy the colour of their matching shape.")
    return out
